CREATE DATABASE solar_analysis;
USE solar_analysis;
SHOW DATABASES;

-- 1. Sales Performance
-- Q1. What is the total net sales generated by B2B Dealers compared with Residential Customers?
SELECT
    customer_type,
    SUM(net_sales_inr) AS total_net_sales
FROM solar_sales
WHERE customer_type IN ('Dealer', 'Residential')
  AND order_status = 'Completed'
GROUP BY customer_type
ORDER BY total_net_sales DESC;

-- Q2. What is the revenue contribution and market share of each solar equipment brand?
SELECT
    brand,
    SUM(net_sales_inr) AS total_sales,
    ROUND(
        100 * SUM(net_sales_inr) /
        SUM(SUM(net_sales_inr)) OVER (),
        2
    ) AS revenue_share_percentage
FROM solar_sales
WHERE order_status = 'Completed'
GROUP BY brand
ORDER BY total_sales DESC;

-- Q3. Which dealer accounts used discounts while maintaining an average order value above the overall average?
SELECT
    customer_id,
    COUNT(*) AS order_count,
    SUM(net_sales_inr) AS total_sales,
    ROUND(AVG(net_sales_inr), 2) AS average_order_value
FROM solar_sales
WHERE customer_type = 'Dealer'
  AND discount_pct > 0
  AND order_status = 'Completed'
GROUP BY customer_id
HAVING AVG(net_sales_inr) > (
    SELECT AVG(net_sales_inr)
    FROM solar_sales
    WHERE order_status = 'Completed'
)
ORDER BY average_order_value DESC LIMIT 5;

-- Q4. How does quarterly net sales and order volume trend across the financial year?
SELECT
    CASE
        WHEN MONTH(transaction_date) BETWEEN 4 AND 6 THEN 'Q1'
        WHEN MONTH(transaction_date) BETWEEN 7 AND 9 THEN 'Q2'
        WHEN MONTH(transaction_date) BETWEEN 10 AND 12 THEN 'Q3'
        ELSE 'Q4'
    END AS quarter,
    COUNT(DISTINCT transaction_id) AS order_volume,
    SUM(net_sales_inr) AS quarterly_net_sales
FROM solar_sales
WHERE order_status = 'Completed'
GROUP BY
    CASE
        WHEN MONTH(transaction_date) BETWEEN 4 AND 6 THEN 'Q1'
        WHEN MONTH(transaction_date) BETWEEN 7 AND 9 THEN 'Q2'
        WHEN MONTH(transaction_date) BETWEEN 10 AND 12 THEN 'Q3'
        ELSE 'Q4'
    END
ORDER BY
    FIELD(quarter, 'Q1', 'Q2', 'Q3', 'Q4');
    ;
    
-- Q5. Which product categories have the highest percentage of discounted orders?
SELECT
    product_category,
    COUNT(*) AS total_orders,
    SUM(
        CASE
            WHEN discount_pct > 0 THEN 1
            ELSE 0
        END
    ) AS discounted_orders,
    ROUND(
        100 * SUM(
            CASE
                WHEN discount_pct > 0 THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        2
    ) AS discounted_order_percentage
FROM solar_sales
WHERE order_status = 'Completed'
GROUP BY product_category
ORDER BY discounted_order_percentage DESC;

-- 2. Operations & Fulfillment
-- Q6. What is the distribution of completed orders across different shipping types?
SELECT
    shipping_type,
    COUNT(*) AS shipment_count,
    SUM(quantity) AS units_shipped,
    SUM(net_sales_inr) AS equipment_value
FROM solar_sales
WHERE order_status = 'Completed'
GROUP BY shipping_type
ORDER BY shipment_count DESC;

-- Q7. What are the top 3 most demanded equipment models within each product category?
WITH product_demand AS (
    SELECT
        product_category,
        product_name,
        SUM(quantity) AS total_quantity
    FROM solar_sales
    WHERE order_status = 'Completed'
    GROUP BY
        product_category,
        product_name
),
ranked_products AS (
    SELECT
        product_category,
        product_name,
        total_quantity,
        RANK() OVER (
            PARTITION BY product_category
            ORDER BY total_quantity DESC
        ) AS product_rank
    FROM product_demand
)
SELECT
    product_category,
    product_name,
    total_quantity,
    product_rank
FROM ranked_products
WHERE product_rank <= 3
ORDER BY
    product_category,
    product_rank LIMIT 5;

-- Q8. How does average order value compare between Express Delivery and Standard Delivery orders?
SELECT
    shipping_type,
    COUNT(*) AS order_count,
    ROUND(AVG(net_sales_inr), 2) AS average_order_value
FROM solar_sales
WHERE shipping_type IN (
    'Express Delivery',
    'Standard Delivery'
)
AND order_status = 'Completed'
GROUP BY shipping_type
ORDER BY average_order_value DESC;

-- Q9. What is the installation volume and equipment value distributed across different cities?
SELECT
    customer_city,
    COUNT(*) AS installation_orders,
    SUM(quantity) AS equipment_units,
    SUM(net_sales_inr) AS equipment_value
FROM solar_sales
WHERE installation_required = 'Yes'
  AND order_status = 'Completed'
GROUP BY customer_city
ORDER BY equipment_value DESC;

-- 3. Customer Insights
-- Q10. How are customers distributed based on their purchasing history?
WITH customer_orders AS (
    SELECT
        customer_id,
        customer_type,
        COUNT(*) AS order_count,
        SUM(net_sales_inr) AS lifetime_sales
    FROM solar_sales
    WHERE order_status = 'Completed'
    GROUP BY
        customer_id,
        customer_type
)
SELECT
    customer_type,
    CASE
        WHEN order_count = 1
            THEN 'New Account'
        WHEN order_count BETWEEN 2 AND 5
            THEN 'Returning Account'
        ELSE 'High-Frequency Account'
    END AS customer_segment,
    COUNT(*) AS customer_count,
    SUM(lifetime_sales) AS segment_revenue
FROM customer_orders
GROUP BY
    customer_type,
    customer_segment
ORDER BY segment_revenue DESC;

-- Q11. Which customers have placed the highest number of orders and generated the highest lifetime revenue?
SELECT
    customer_id,
    customer_type,
    COUNT(*) AS total_orders,
    SUM(net_sales_inr) AS lifetime_revenue,
    ROUND(AVG(net_sales_inr), 2) AS average_order_value
FROM solar_sales
WHERE order_status = 'Completed'
GROUP BY
    customer_id,
    customer_type
ORDER BY
    total_orders DESC,
    lifetime_revenue DESC
LIMIT 5;